    "answer": "a",
    "full": "a huge source of revenue / the very foundation of our business / one-off jobs",
    "said": "This type of building, the apartment complex, we have to do like two or three, maybe two in a year, and that's a huge revenue, a very good foundation of my company, relying on this kind of job, few months involvement. It's very foundation of our company's business. And in months, the shop renovation, kind of spot job, two or three that kind of jobs in a month. That's what we are doing.",
    "why": "revenue は source of revenue で受ける(#13)。'It's very foundation'→the VERY foundation(theが要る)。単発仕事= one-off jobs、spot jobは和製寄り",
